function persist(){
  if(!process.env.DATABASE_URL || !pool){fs.writeFileSync(DB_FILE,JSON.stringify(db,null,2));return Promise.resolve();}
  const snapshot=JSON.stringify(db);
  persistQueue=persistQueue.then(()=>pool.query("INSERT INTO tantera_app_state (id,data,updated_at) VALUES (1,$1::jsonb,now()) ON CONFLICT (id) DO UPDATE SET data=EXCLUDED.data,updated_at=now()",[snapshot]));
  return persistQueue;
}
async function initDb(){
  if(!process.env.DATABASE_URL)return;
  pool=new Pool({connectionString:process.env.DATABASE_URL,ssl:process.env.DATABASE_SSL==="false"?false:{rejectUnauthorized:false},max:5});
  await pool.query("CREATE TABLE IF NOT EXISTS tantera_app_state (id integer PRIMARY KEY CHECK (id = 1), data jsonb NOT NULL, updated_at timestamptz NOT NULL DEFAULT now())");
  const result=await pool.query("SELECT data FROM tantera_app_state WHERE id=1");
  if(result.rows[0]?.data)db=result.rows[0].data;
  else await persist();
  console.log("Persistência PostgreSQL ativa (Neon)");
}
function body(req){return new Promise((resolve,reject)=>{let raw="";req.on("data",c=>raw+=c);req.on("end",()=>{try{resolve(raw?JSON.parse(raw):{})}catch{reject(new Error("JSON inválido"))}});req.on("error",reject)})}
function send(res,status,data,headers={}){res.writeHead(status,{"Content-Type":"application/json; charset=utf-8",...headers});res.end(JSON.stringify(data));}
function cookie(req,name){return (req.headers.cookie||"").split(";").map(x=>x.trim().split("=")).find(x=>x[0]===name)?.[1]}
function userFrom(req){const token=cookie(req,"tantera_session");const uid=sessions.get(token);return uid&&db.users.find(u=>u.id===uid&&u.active)||null}
function safeUser(u){return u&&{id:u.id,name:u.name,email:u.email,role:u.role,area:u.area,active:u.active,mustChangePassword:u.mustChangePassword};}
function requireAuth(req,res){const u=userFrom(req);if(!u){send(res,401,{error:"Faça login para acessar a Área da equipe."});return null}return u}
function isLeader(u){return u.role==="presidente"} function canArea(u,area){return isLeader(u)||u.area===area}
const FIVE_DAYS=5*24*60*60*1000;
function canDeleteCreated(u,item){const owner=item.createdBy||item.submittedBy;return isLeader(u)||(owner===u.id&&item.createdAt&&Date.now()-new Date(item.createdAt).getTime()<=FIVE_DAYS)}
function canEvents(u){return isLeader(u)||u.area==="Eventos"}
function canProducts(u){return isLeader(u)||u.area==="Produtos"}
function canFinance(u){return isLeader(u)||u.area==="Financeiro"}
